    "s22_category": "Teil 3: Hammerkopf-Produktion • Vorformung",
    "s22_title": "Vorformung des Bassfilzes & Biegekurven",
    "s22_subtitle": "Ausbildung der charakteristischen Spannungsbögen vor dem Schließen der Presse",
    "s22_bullet_1": "<strong>Elastische Vorbiegung:</strong> Das dicke Bass-Ende des Filzstreifens wird vor dem Einbringen in die Pressform vorkonditioniert.",
    "s22_bullet_2": "<strong>Charakteristische Kurven:</strong> Entlang des Streifens bilden sich harmonische Wellen, die den späteren Druckfluss abbilden.",
    "s22_bullet_3": "<strong>Gleichmäßige Dehnung:</strong> Verhindert das Reißen äußerer Faserlagen beim engen Umschließen der Kernholzspitze.",
    "s22_caption_1": "Bass-Ende des Filzstreifens mit charakteristischen Biegekurven vor dem Pressen",
    "s22_b1_badge": "VORFORMUNG",
    "s22_b2_badge": "BIEGEKRAFT",
