    "s23_category": "Teil 3: Hammerkopf-Produktion • Pressprozess",
    "s23_title": "Pressen & Verleimen: Zug- und Druckkräfte im Filz",
    "s23_subtitle": "Nachspannen des Kernholzes zur Erzeugung maximaler elastischer Außenspannung",
    "s23_bullet_1": "<strong>Schließen der Seitenbacken:</strong> Die temperierten Pressbacken umschließen den Filz seitlich und führen ihn um das beleimte Kernholz.",
    "s23_bullet_2": "<strong>Kernholz nachspannen:</strong> Nachdem die Seitenbacken geschlossen sind, wird das Kernholz nochmals mit Hochdruck nachgespannt.",
    "s23_bullet_3": "<strong>Zugspannung in den Außenlagen:</strong> Durch diesen Renner-spezifischen Schritt erhalten die äußeren Filzlagen eine unerreichte Vorspannung.",
    "s23_bullet_4": "<strong>Basis für die spätere Intonation:</strong> Diese elastische Eigenspannung erlaubt späteres Intonieren mit unvergleichlicher Dynamikspreizung.",
    "s23_caption_1": "Press- und Verleimvorgang des Hammerkopfs unter Hochdruck",
    "s23_b1_badge": "HOCHDRUCK-PRESSEN",
    "s23_b2_badge": "WERKSVIDEO",
    "s23_notes": "Folie 23: Erläutern Sie die wesentlichen technischen Parameter und Qualitätskriterien aus den Renner Academy Unterlagen.",
    "s24_category": "Teil 3: Hammerkopf-Produktion • Hammerkopf-Riegel",
    "s24_title": "Der Hammerkopf-Riegel im Rohzustand",
    "s24_subtitle": "Entformung des monolithischen 88er-Riegels nach dem Aushärten des Leims",
    "s24_bullet_1": "<strong>Perfekte Leimfuge:</strong> Vollflächige Verbindung zwischen Holz, Unterfilz und Deckfilz ohne Lufteinschlüsse.",
    "s24_bullet_2": "<strong>Harmonischer Übergang:</strong> Die Kernform zeichnet sich präzise unter dem komprimierten Filz ab.",
    "s24_bullet_3": "<strong>Betriebsgeheimnis der Formgebung:</strong> Bestimmte nachgelagerte Warmformschritte unterliegen dem strengen Renner-Verfahrensschutz.",
    "s24_caption_1": "Der verleimte Hammerkopf-Riegel direkt nach dem Entformen",
    "s24_b1_badge": "RIEGEL-FERTIGUNG",
    "s24_b2_badge": "PRESS-RIEGEL",
