    "s25_category": "Teil 3: Hammerkopf-Produktion • CNC-Bearbeitung",
    "s25_title": "CNC-Bearbeitung & Abrichten des Riegels",
    "s25_subtitle": "Mehrachsiges Fräsen der Flanken und Trennen in 88 Einzelexemplare",
    "s25_bullet_1": "<strong>CNC-Abrichten der Leisten:</strong> Beseitigung von Leimaustritten und exaktes Ausfräsen der Außenradien.",
    "s25_bullet_2": "<strong>Hochgeschwindigkeits-Fräsen:</strong> Spezialwerkzeuge schneiden den dichten Wollfilz mit rasiermesserscharfen Kanten ohne Faserausriss.",
    "s25_bullet_3": "<strong>Präzises Auftrennen:</strong> Trennen des Riegels in exakt abgestimmte Breiten (Bass ca. 11,5 mm bis Diskant ca. 9,5–10 mm).",
    "s25_caption_1": "CNC-Präzisionsfräszentrum in Meuselwitz bei der Leistenbearbeitung",
    "s25_b1_badge": "CNC-ABRICHTEN",
    "s25_b2_badge": "CNC-FRÄSUNG",
