    "s26_category": "Teil 3: Hammerkopf-Produktion • Bohren & Vernieten",
    "s26_title": "Bohrung, T-Vernietung & Veredelung",
    "s26_subtitle": "Präzise Stielbohrung im Raumwinkel und formschlüssige Messing-T-Niete",
    "s26_bullet_1": "<strong>Automatisierte Stielbohrung:</strong> Bohren im exakten Raumwinkel (Bohrungslänge, Durchmesser ø 5,4 mm, Neigungswinkel in Gon).",
    "s26_bullet_2": "<strong>T-Vernietung (Riveting):</strong> Hochfeste Messing-T-Nieten sichern die Filzschenkel dauerhaft gegen Aufplatzen bei stärksten Konzertanschlägen.",
    "s26_bullet_3": "<strong>Verrundung der Hammerschwänze:</strong> Speziell geformte Radien am Schwanz erleichtern später das Einpassen in den Fänger.",
    "s26_caption_1": "Bohren und Einbringen der T-Nieten in Meuselwitz",
    "s26_b1_badge": "VEREDELUNG & ENDBEARBEITUNG",
