    "s27_category": "Teil 3: Hammerkopf-Produktion • Qualität & Nutzen",
    "s27_title": "Die 6 Kernvorteile der neuen Renner-Hammerköpfe",
    "s27_subtitle": "Zusammenfassung der Innovationskraft aus dem Vortrag von Clemens Kunert",
    "s27_c1_title": "1. Maßgeschneiderte Fertigung",
    "s27_c2_title": "2. Direkt fertig zur Endintonation",
    "s27_c3_title": "3. Höchste Fertigungspräzision",
    "s27_c4_title": "4. Überragende Klangstabilität",
    "s27_c5_title": "5. Reiches Obertonspektrum",
    "s27_c6_title": "6. Einbaufertig veredelt",
    "s27_c1_desc": "Individuelle Sonderanfertigung von Einzelstücken für historische Schätze bis hin zu großen Konzert-Serien.",
    "s27_c2_desc": "Keine zeitraubende Vorintonation am Instrument mehr nötig! Der Satz ist ab Werk klanglich vorbereitet.",
    "s27_c3_desc": "Kombination aus traditionellem FFW-Filzhandwerk und mikrometergenauer Roboter- und CNC-Bearbeitung.",
    "s27_c4_desc": "Durch die Eigenspannung des Weickert-Special-Filzes bleibt das Klangbild über viele Jahre hinweg stabil.",
    "s27_c5_desc": "Breiteste Dynamikspreizung vom zartesten Pianissimo bis zum tragfähigen Fortissimo im großen Konzertsaal.",
    "s27_c6_desc": "Präzise gebohrt, formschlüssig vernietet, mit verrundeten Schwanzenden und veredelter Scheitelkontur.",
    "s27_b1_badge": "MASSGESCHNEIDERT",
    "s27_b2_badge": "EFFIZIENZ",
