    "s28_category": "Teil 4: Musterteilekoffer • Systemübersicht",
    "s28_title": "Der Renner Musterteilekoffer (MTK)",
    "s28_subtitle": "Das unverzichtbare Diagnose- und Auswahlinstrument für die Reparaturwerkstatt",
    "s28_bullet_1": "<strong>Direkte Passprüfung:</strong> Musterteile können direkt im Kundeninstrument eingehängt und getestet werden.",
    "s28_bullet_2": "<strong>Umfassendes Fachhandbuch:</strong> Ausführliche Tabellen mit Hebellängen, Winkeln und Kapselabständen.",
    "s28_bullet_3": "<strong>Vermeidung von Fehlbestellungen:</strong> Eindeutige Renner-Artikelnummern für reibungslose Nachbestellung.",
