    "s29_title": "15 Flügel-Hebeglieder & 12 Wechselsättel",
    "s29_subtitle": "Lückenlose Abdeckung aller Hebelverhältnisse für Flügel aller Epochen",
    "s29_bullet_1": "<strong>15 verschiedene Hebeglied-Varianten:</strong> Jeweils 2 Stück pro Modell als Testmuster im Koffer enthalten.",
    "s29_bullet_2": "<strong>2 Modelle ohne Sattel:</strong> Ermöglichen individuelle Anpassungen bei historischen Sonderkonstruktionen.",
    "s29_bullet_3": "<strong>12 kombinierbare Sättel:</strong> Unterschiedliche Sattelhöhen und Neigungen zur Feinabstimmung der Steighöhe.",
    "s29_bullet_4": "<strong>Sofortige Lieferbarkeit:</strong> Alle 15 Hebeglied-Typen sind bei Renner ab Lager als kompletter Reparatursatz verfügbar.",
