    "s39_category": "Teil 5: Maßblätter & Geometrie • Gon-Winkel",
    "s39_title": "Bohrwinkel in Gon (100er-Teilung des 90°-Winkels)",
    "s39_subtitle": "Warum Renner Bohrwinkel traditionell in Gon statt in Grad angibt",
