    "s39_b2_badge": "BOHRWINKEL-TABELLE",
    "s39_c1_title": "Zehntelgrad-genaue Teilung ohne Bruchminuten",
    "s39_c1_desc": "Gon ermöglicht feinere, zehntelgrad-genaue Teilungen ohne Bruchminuten. Normalwerte:",
    "s39_caption_1": "Bohrwinkeltabelle in Gon",
