    "s14_category": "Part 2: Felt Manufacturing • Filz-Identifikation",
    "s14_title": "The Core 'Soul': Trademark of Wurzen Felt Sheets",
    "s14_subtitle": "1 or 2 colored indicator layers at the bass edge as traditional proof of origin",
    "s14_bullet_1": "<strong>What is the 'Soul'?</strong> A thin, distinctly colored felt layer integrated at the bass edge during sheet fabrication.",
    "s14_bullet_2": "<strong>Traditional Proof of Origin:</strong> A historic hallmark of Wurzen felt authenticity, recognized by piano builders worldwide.",
    "s14_bullet_3": "<strong>No Difference in Quality:</strong> Sheets with 1 or 2 indicator layers share identical fiber specs – they serve batch tracking and visual authenticity.",
    "s14_caption_1": "Felt strip showing visible indicator layer ('soul') at the bass origin",
    "s14_b1_badge": "HALLMARK",
    "s14_b2_badge": "DENSITY GRADIENT",
