    "s15_category": "Part 2: Felt Manufacturing • Weickert Special",
    "s15_title": "“Weickert Special”: Exclusively for Louis Renner",
    "s15_subtitle": "Highest lanolin retention for unsurpassed voicing stability and tonal response",
    "s15_c1_title": "What makes 'Weickert Special' so unique?",
    "s15_bullet_1": "<strong>Exclusive Formulation:</strong> Manufactured by Filzfabrik Wurzen exclusively for Louis Renner.",
    "s15_bullet_2": "<strong>Higher Wool Grease (Lanolin) Retention:</strong> A gentle proprietary wash preserves more natural lanolin inside the fibers.",
    "s15_bullet_3": "<strong>Reduced Hygroscopic Swelling:</strong> Substantially less sensitive to seasonal swings in atmospheric humidity.",
    "s15_bullet_4": "<strong>Enhanced Clamping Tension:</strong> Exceptional adhesion and dynamic self-tension around the wooden hammer moulding.",
    "s15_bullet_5": "<strong>Enduring Voicing Stability:</strong> The voiced tonal profile remains exceptionally stable over years of concert play.",
    "s15_caption_1": "Weickert Special: Finest wool fiber quality engineered for maximum longevity",
    "s15_b1_badge": "EXCLUSIVITY",
    "s15_b2_badge": "WEICKERT SPECIAL",
    "s15_notes": "Slide 15: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s16_category": "Part 3: Hammerkopf-Produktion • Roboter-Zuschnitt",
    "s16_title": "Robotic Felt Cutting: Supreme Cutting Accuracy",
    "s16_subtitle": "Computer-controlled cutting lines with micro-stepper motors and laser guidance",
    "s16_bullet_1": "<strong>Tapered Strip Cutting:</strong> Micro-stepper motors guide the blade along the exact wedge profile (thick bass to thin treble).",
    "s16_bullet_2": "<strong>Laser Line Guidance:</strong> Real-time laser projection monitors cutting paths with tolerance under 0.05 mm.",
    "s16_bullet_3": "<strong>Individual Customer Tapers:</strong> Continuous wedge angles can be configured for every manufacturer and scale design.",
    "s16_bullet_4": "<strong>Industry 4.0 in Piano Making:</strong> Digital traceability from raw wool bale to finished hammerhead.",
    "s16_caption_1": "Modern robotic felt cutting center at the Meuselwitz plant",
    "s16_b1_badge": "ROBOTICS",
    "s16_b2_badge": "FACTORY VIDEO MEUSELWITZ",
    "s16_notes": "Slide 16: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s17_category": "Part 3: Hammerkopf-Produktion • Deckfilz-Qualität",
    "s17_title": "Edge Quality & Fiber Integrity in Top Felt Strips",
    "s17_subtitle": "Razor-sharp vertical cuts prevent skewed stretching during hammer moulding",
    "s17_bullet_1": "<strong>100% Vertical Cut Edge:</strong> Prevents distortion and uneven fiber elongation during subsequent high-pressure pressing.",
    "s17_bullet_2": "<strong>No Crushed Fibers:</strong> Clean cutting preserves internal fiber voids, ensuring unconstrained compression dynamics.",
    "s17_bullet_3": "<strong>Prevention of Skewing:</strong> Only strictly rectangular cut strips wrap around the wooden moulding with absolute lateral symmetry.",
    "s17_caption_1": "Inspected top felt strip: Tapered profile and homogeneous fiber matrix",
    "s17_b1_badge": "QUALITY CONTROL",
    "s17_b2_badge": "TOP FELT STRIPS",
    "s17_notes": "Slide 17: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s18_category": "Part 3: Hammerkopf-Produktion • Unterfilz",
    "s18_title": "Underfelt Profiling: Base Foundation of Tension",
    "s18_subtitle": "Precision profiling of underfelt strips for optimal cushioning and energy transmission",
    "s18_bullet_1": "<strong>Function of Underfelt:</strong> Acts as an elastic buffer between the rigid wood moulding and resilient top felt.",
    "s18_bullet_2": "<strong>Precision Profiling:</strong> In Meuselwitz, underfelt strips are shaped on dedicated multi-axis milling machines prior to gluing.",
    "s18_bullet_3": "<strong>Even Pressure Distribution:</strong> The profiled contour ensures press clamping force flows smoothly into the hammer flanks.",
    "s18_caption_1": "Profiling the underfelt strip on specialized Renner milling machinery",
    "s18_b1_badge": "UNDERFELT MILLING",
