    "s21_c1_desc": "For Steinway & Sons (historic and modern), Bösendorfer, Schimmel, C. Bechstein, Yamaha, Kawai, Grotrian-Steinweg, Petrof, August Förster, Sauter, Blüthner, and Renner USA.",
    "s21_c2_desc": "Historic Bechstein designs, grands with ultra-slender treble progressions, and custom mouldings balancing moment of inertia against steep string angles.",
