    "s22_category": "Part 3: Hammerkopf-Produktion • Vorformung",
    "s22_title": "Bass Felt Pre-Forming & Bending Curvatures",
    "s22_subtitle": "Developing characteristic tension arches before closing the press",
    "s22_bullet_1": "<strong>Elastic Pre-Bending:</strong> The heavy bass end of the felt strip is pre-conditioned before loading into the press fixture.",
    "s22_bullet_2": "<strong>Characteristic Contours:</strong> Harmonious wave profiles form along the strip, mirroring subsequent pressure vectors.",
    "s22_bullet_3": "<strong>Uniform Elongation:</strong> Prevents outer fiber tearing when tightly encircling the apex of the wooden moulding.",
    "s22_caption_1": "Bass end of felt strip exhibiting characteristic pre-bending curves before pressing",
    "s22_b1_badge": "PRE-FORMING",
    "s22_b2_badge": "BENDING FORCE",
    "s22_notes": "Slide 22: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s23_category": "Part 3: Hammerkopf-Produktion • Pressprozess",
    "s23_title": "Pressing & Glueing: Tension & Compression Equilibrium",
    "s23_subtitle": "Re-tensioning the wooden moulding to build maximum elastic outer tension",
    "s23_bullet_1": "<strong>Closing Side Jaws:</strong> Temperature-controlled press jaws flank the felt and wrap it around the glued wooden moulding.",
    "s23_bullet_2": "<strong>Re-tensioning the Moulding:</strong> Once side jaws are closed, high hydraulic pressure re-tensions the core moulding downwards.",
    "s23_bullet_3": "<strong>Tensile Pre-Stress in Outer Layers:</strong> This proprietary Renner technique imparts unmatched dynamic pre-tension to outer felt layers.",
    "s23_bullet_4": "<strong>Foundation for Voicing:</strong> This elastic stored energy enables subsequent voicing with extraordinary dynamic range.",
    "s23_caption_1": "Hammerhead pressing and gluing process under high hydraulic pressure",
    "s23_b1_badge": "HIGH-PRESSURE PRESSING",
    "s23_b2_badge": "FACTORY VIDEO",
    "s23_notes": "Slide 23: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s24_category": "Part 3: Hammerkopf-Produktion • Hammerkopf-Riegel",
    "s24_title": "The Raw Hammerhead Moulding Bar after Pressing",
    "s24_subtitle": "De-moulding the monolithic 88-note block after glue cure",
    "s24_bullet_1": "<strong>Flawless Glue Line:</strong> Continuous bonding between wood, underfelt, and top felt with zero air pockets.",
    "s24_bullet_2": "<strong>Harmonious Transition:</strong> The moulding contour imprints crisply beneath the compacted felt envelope.",
    "s24_bullet_3": "<strong>Proprietary Thermo-Forming:</strong> Dedicated post-cure thermal stabilization remains a strictly guarded Renner trade secret.",
    "s24_caption_1": "The bonded hammerhead block immediately following de-moulding",
