    "s25_category": "Part 3: Hammerkopf-Produktion • CNC-Bearbeitung",
    "s25_title": "CNC Machining & Truing of the Moulding Bar",
    "s25_subtitle": "Multi-axis flank milling and slicing into 88 individual hammerheads",
    "s25_bullet_1": "<strong>CNC Truing of Blocks:</strong> Removal of glue beads and high-precision milling of outer moulding contours.",
    "s25_bullet_2": "<strong>High-Speed Milling:</strong> Specialized tooling cuts dense wool felt with razor-sharp edges without fiber pullout.",
    "s25_bullet_3": "<strong>Precision Slicing:</strong> Slicing the block into exact progressive widths (approx. 11.5 mm bass to 9.5–10 mm treble).",
    "s25_caption_1": "CNC precision milling center in Meuselwitz machining hammerhead blocks",
