    "s26_bullet_1": "<strong>Automated Shank Boring:</strong> Boring at exact spatial angles (bore depth, diameter ø 5.4 mm, inclination in gon).",
    "s26_bullet_2": "<strong>T-Riveting:</strong> High-tensile brass T-rivets permanently secure felt flanks against bursting under fortissimo concert attacks.",
    "s26_bullet_3": "<strong>Tail Radiusing:</strong> Specially shaped tail profiles facilitate smooth engagement with the backcheck.",
