    "s59_c3_title": "Orange Wedge",
    "s59_c4_title": "Violet Wedge",
    "s59_c5_title": "DO NOT TOUCH! – Never prick deeply here!",
    "s59_c1_desc": "Deep needle stitches for tension release",
    "s59_c2_desc": "Projection, brilliance, and dynamic blossoming",
    "s59_c3_desc": "Lyrical singing tone, nuanced balance",
    "s59_c4_desc": "Whisper-soft pianissimo response",
    "s59_caption_1": "Original Renner Clock Model",
