    "s59_notes": "Slide 59: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s60_category": "Part 7: Voicing • Vorintonation",
    "s60_title": "Pre-Voicing (Pre-Needling): Deep 90° Stitches in Blue Wedge",
    "s60_subtitle": "Relieving factory pre-tension and channeling elastic energy into the forte wedge",
    "s60_bullet_1": "<strong>Work Zone:</strong> Exclusively in the blue fortissimo wedge (clock zones 9:00–10:00 and 2:00–3:00).",
    "s60_bullet_2": "<strong>Deep Needling:</strong> Insert needles deeply to just short of the underfelt (never pierce underfelt or core wood!).",
    "s60_bullet_3": "<strong>Tension Transfer:</strong> The head sheds rigid factory stiffness; stored tension flows into the green forte wedge.",
    "s60_bullet_4": "<strong>Recommendation:</strong> This step is recommended almost without exception prior to first playing-in in the instrument.",
    "s60_caption_1": "Pre-needling: Deep stitches in the fortissimo wedge (9:00 to 10:00 o'clock)",
    "s60_b1_badge": "PRE-NEEDLING",
    "s60_b2_badge": "BASIC ELASTICITY",
    "s60_notes": "Slide 60: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s61_category": "Part 7: Voicing • Werkzeug & Technik",
    "s61_title": "Needle Insertion Standards & Voicing Tools",
    "s61_subtitle": "Press, do not chop – Exact stitch counts for bass, mid-range, and treble",
    "s61_bullet_1": "<strong>Stitch Counts for Pre-Needling:</strong> <br>• Bass: 7–10 stitches horizontally <br>• Mid-Range: 5–10 stitches horizontally <br>• Treble: 0–7 stitches vertically",
    "s61_bullet_2": "<strong>Press, never chop!</strong> Press needles steadily using body weight. Chopping tears wool fibers uncontrollably!",
    "s61_bullet_3": "<strong>Original Renner Tools:</strong> <br>• Adjustable Voicing Tool (item 43-0005642) <br>• 3-Needle Voicing Tool Professional (item 43-0003270) <br>• Nickel-plated needles no. 7 ø 0.60 mm, 9 mm long (item 43-0003426).",
    "s61_caption_1": "Renner voicing tools, needle handles, and adjustable voicing instrument",
    "s61_b1_badge": "TOOL SET",
    "s61_b2_badge": "PRECISION NEEDLES",
    "s61_notes": "Slide 61: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s62_category": "Part 7: Voicing • Saitenlagerung",
    "s62_title": "String Preparation: Hitch Pins, Bridge Pins & Leveling",
    "s62_subtitle": "“The finest hammerhead can only reveal what is programmed into the instrument!”",
    "s62_caption_1": "Bedding strings firmly at the hitch pin using brass drift punch",
    "s62_b1_badge": "STRING BEDDING",
    "s62_b2_badge": "UNISON PURITY",
    "s62_bullet_1": "<strong>Setting Hitch Pins:</strong> Carefully seat strings from back to front at hitch pins using a brass drift punch and light hammer.",
    "s62_bullet_2": "<strong>Bridge Pin Alignment:</strong> Seat strings on the bridge with Renner bridge punch to eliminate false beats.",
    "s62_bullet_3": "<strong>Unison Purity:</strong> Before the first voicing needle, the unison must ring absolutely pure and free of unwanted friction.",
    "s62_notes": "Slide 62: Present the key highlights and emphasize Louis Renner's German precision craftsmanship.",
    "s63_category": "Part 7: Voicing • Ausrichtung",
    "s63_title": "Treble Strike Point Alignment & Hammer Straightness",
    "s63_subtitle": "Optimizing notes 69–88 by micro-shifting the keyframe strike line",
    "s63_bullet_1": "<strong>Test Strike Point on Note 88:</strong> Shift keyframe slightly forward and back to locate the brightest, most singing treble sweet spot.",
    "s63_bullet_2": "<strong>Optimize Notes 69 to 88:</strong> The high treble on many grands improves dramatically once the strike line is precisely repositioned!",
    "s63_bullet_3": "<strong>Squareness of All Hammers:</strong> Test by plucking strings or lifting jacks with finger; mark corrections with chalk on key tops.",
    "s63_caption_1": "Verifying treble strike point and square alignment of hammerheads",
