    "s65_title": "Intermediate & Fine Voicing: The 2 mm Limit at the Crown",
    "s65_subtitle": "Chromatic listening and delicate evening-out of individual notes",
    "s65_bullet_1": "<strong>Chromatic Play-Through:</strong> Play chromatically up and down the keyboard; flag notes with harsh attack or uneven volume.",
    "s65_bullet_2": "<strong>Mid-Voicing:</strong> Gentle needle pricks in green forte and orange piano wedges. Overly soft notes are firmed by light surface sanding!",
    "s65_bullet_3": "<strong>Final Voicing:</strong> Short single needle (BDK handle item 43-0003269 or Chop Stick item 43-0003271).",
    "s65_bullet_4": "<strong>Max. 2 mm Depth at Crown:</strong> Insert only between string grooves, never directly into the string depressions!",
