    "s5_title": "J.D.ヴァイケルトとハンマーフェルトの原点",
    "s5_subtitle": "1783 in Leipzig gegründet – 1847 Eröffnung der Spezialfabrik in Wurzen",
    "s5_bullet_1": "<strong>Gründung 1783:</strong> Gegründet von Johann David Weickert in Leipzig (Sachsen). Ursprünglich Tuch- und Filzherstellung.",
    "s5_bullet_2": "<strong>Pionierleistung 1847:</strong> In der neu errichteten Fabrik in Wurzen gelang es erstmals, speziellen Hammerkopffilz in gleichbleibender Spitzenqualität zu fertigen, wie er bis heute genutzt wird.",
    "s5_bullet_3": "<strong>Weltweiter Hoflieferant:</strong> Bereits im 19. Jahrhundert belieferte Weickert die renommiertesten Pianoforte-Fabrikanten Europas und Amerikas.",
    "s5_bullet_4": "<strong>Klangliche Identität:</strong> Weickert-Filz gilt weltweit als der Inbegriff des warmen, tragfähigen und farbenreichen europäischen Klaviertons.",
    "s5_caption_1": "Original Weickert-Manufaktur in Wurzen (Sachsen)",
