    "s6_subtitle": "Traditionelles Handwerkswissen vereint mit modernsten Produktionsstandards",
    "s6_bullet_1": "<strong>Exklusive Renner-Partnerschaft:</strong> Renner bezieht seinen gesamten Premium-Deckfilz exklusiv aus der modernisierten Wurzener Manufaktur.",
    "s6_bullet_2": "<strong>Traditionsmeister:</strong> Das tiefe Wissen erfahrener Altmeister über Wollfeuchte, Walkzeiten und Faserrezepturen wird sorgfältig weitergegeben.",
    "s6_bullet_3": "<strong>Modernisierte Anlagen:</strong> Präzise Temperatur- und Drucküberwachung für unerreichte Chargenkonstanz.",
    "s6_caption_1": "Filzfabrik Wurzen (FFW): Traditionelle Fertigung auf modernem Niveau",
