    "s7_category": "第2部：極上フェルト製造の秘密（ヴルツェン工場）",
    "s7_title": "厳選バージンウール：天然繊維の弾力性保護",
    "s7_subtitle": "Nur unverpresste Rohwolle garantiert die maximale natürliche Elastizität",
    "s7_bullet_1": "<strong>Ballenlieferung ohne Überpressung:</strong> Die Rohwolle wird in locker gepackten Ballen transportiert. Zu starkes Verpressen würde die empfindlichen Schuppen und Biegungen der Wollfasern irreversibel schädigen.",
    "s7_bullet_2": "<strong>Höhere Logistikkosten für Spitzenqualität:</strong> Dieser schonende Transport erhöht das Transportvolumen, sichert jedoch die unversehrte Faserelastizität.",
    "s7_bullet_3": "<strong>Starke Faserkräuselung:</strong> Nur hochgradig gekräuselte Merinowollfasern bieten beim späteren Walkprozess den optimalen Verhakungseffekt.",
    "s7_bullet_4": "<strong>Schonende Carbonisierung:</strong> Chemisch sanftes Reinigungsverfahren entfernt Pflanzenteilchen, ohne die Proteinstruktur des Keratins anzugreifen.",
    "s7_caption_1": "Anlieferung der Rohwolle: Schonend gelagerte Wollballen bei FFW",
    "s7_b1_badge": "原料選定",
    "s7_b2_badge": "非圧縮ベール",
    "s7_notes": "スライド 7: ルイス・レンナー社のドイツ精密製造技術と品質の優位性を解説してください。",
    "s8_category": "第2部：極上フェルト製造の秘密（ヴルツェン工場）",
    "s8_title": "門外不出：門外不出の羊毛配合レシピ",
    "s8_subtitle": "Auflockerung und Mischung verschiedener Wollpartien für maßgeschneiderte Dichten",
    "s8_bullet_1": "<strong>Blend-Verfahren:</strong> Mischen unterschiedlicher Faserlängen und -stärken, um spezifische Federsteifigkeiten zu erzielen.",
    "s8_bullet_2": "<strong>Faserauflockerung:</strong> Mehrstufiges maschinelles Zupfen und Belüften trennt Faserknäuel sanft in Einzelfasern.",
    "s8_bullet_3": "<strong>Klimakonditionierung:</strong> Konstante Feuchteaufnahme vor dem Kardieren verhindert elektrostatische Aufladung und Faserbruch.",
    "s8_caption_1": "Auflockerungs- und Mischprozess der Faserchargen bei FFW Wurzen",
    "s8_b1_badge": "秘伝の配合",
    "s8_b2_badge": "繊維調合",
    "s8_notes": "スライド 8: ルイス・レンナー社のドイツ精密製造技術と品質の優位性を解説してください。",
    "s9_category": "第2部：極上フェルト製造の秘密（ヴルツェン工場）",
    "s9_title": "カーディング（梳毛）：繊維の整列とフリース形成",
    "s9_subtitle": "Die definierte Faserorientierung als Fundament für Schwingung und Saitenansprache",
    "s9_bullet_1": "<strong>Kardieren (Carding):</strong> Die aufgelockerten Fasern werden über feine Nadelwalzen gekämmt, entwirrt und parallel zueinander angeordnet.",
    "s9_bullet_2": "<strong>Definierte Faserrichtung:</strong> Das so entstehende hauchdünne, weiche Vlies besitzt eine exakt vorgegebene Vorzugsrichtung der Fasern.",
    "s9_bullet_3": "<strong>Schichtung:</strong> Mehrere Vlieslagen werden im Kreuz- und Längsverbund übereinandergelegt, um die gewünschte Plattendicke und Dichteverteilung aufzubauen.",
    "s9_bullet_4": "<strong>Voraussetzung für die Intonation:</strong> Nur parallel geordnete Fasern reagieren bei späteren Intonierarbeiten vorhersehbar und gleichmäßig auf Nadelstiche.",
    "s9_caption_1": "Auskämmen der Wolle zu seidig fließenden Vliesen mit definierter Faserrichtung",
