    "s11_c1_title": "Maximale natürliche Walkhärte",
    "s11_c1_desc": "Filzplatten werden beim Walken so lange verdichtet, bis sich die Fasern auf rein mechanischem Wege nicht weiter zusammenschieben lassen. Dies entspricht der maximalen natürlichen Walkhärte von ca. 0.56 Shore.",
