    "s13_category": "第2部：極上フェルト製造の秘密（ヴルツェン工場）",
    "s13_title": "モイゼルヴィッツ調湿保管庫：30種以上のフェルト原反",
    "s13_subtitle": "Konische Plattengeometrie und permanente Reifekontrolle im Werk Meuselwitz",
    "s13_bullet_1": "<strong>Konische Plattenform:</strong> Die Filzplatten sind werkseitig keilförmig aufgebaut – dicker und schwerer im Bass, stetig dünner und dichter werdend zum Diskant hin.",
    "s13_bullet_2": "<strong>Über 30 Rezepturen auf Lager:</strong> Renner hält permanent weit über 30 verschiedene Filzplattensorten von FFW Wurzen vorrätig – mehr als jeder andere Hersteller weltweit.",
    "s13_bullet_3": "<strong>Klimakontrolle & Mottenschutz:</strong> Kontrollierte Luftfeuchte und Pheromonfallen schützen das Naturmaterial dauerhaft.",
    "s13_bullet_4": "<strong>Spannungsfreies Reifen:</strong> Mindestlagerdauer vor dem Zuschnitt baut innere Restspannungen vollständig ab.",
    "s13_caption_1": "Filzplattenlager im Werk Meuselwitz: Über 30 Plattensorten permanent verfügbar",
    "s13_b1_badge": "定温定湿保管",
    "s13_b2_badge": "モイゼルヴィッツ保管庫",
