    "s14_title": "フェルトの「芯（ゼーレ）」：ヴルツェン製原反の証",
    "s14_subtitle": "1 oder 2 farbige Schichten am Bass-Beginn als traditioneller Herkunftsnachweis",
    "s14_bullet_1": "<strong>Was ist die „Seele“?</strong> Eine dünne, andersfarbige Filzschicht, die bei der Plattenherstellung am Bassanfang eingearbeitet wird.",
    "s14_bullet_2": "<strong>Traditioneller Herkunftsnachweis:</strong> Ein historisches Echtheitsmerkmal der Filzfabrik Wurzen für Klavierbauer weltweit.",
    "s14_bullet_3": "<strong>Kein Qualitätsunterschied:</strong> Platten mit 1 oder 2 Seelen besitzen identische Fasereigenschaften – sie dienen der Chargenkennzeichnung und optischen Authentizität.",
    "s14_caption_1": "Filzstreifen mit sichtbarer „Seele“ (farbige Kennzeichnungsschicht am Bassanfang)",
