    "s15_c1_title": "Was macht „Weickert Special“ so einzigartig?",
    "s15_bullet_1": "<strong>Exklusivrezeptur:</strong> Wird von der Filzfabrik Wurzen ausschließlich für Renner gefertigt.",
    "s15_bullet_2": "<strong>Höherer Wollfettgehalt (Lanolin):</strong> Spezieller Waschprozess belässt mehr natürliches Lanolin in der Faser.",
    "s15_bullet_3": "<strong>Reduziertes Quellverhalten:</strong> Deutlich unempfindlicher gegenüber jahreszeitlichen Luftfeuchteschwankungen.",
    "s15_bullet_4": "<strong>Verbesserte Traktionskräfte:</strong> Außergewöhnliche Adhäsion und Eigenspannung am Holzkern.",
    "s15_bullet_5": "<strong>Dauerhafte Intonationshaltung:</strong> Der einmal intonierte Klangcharakter bleibt über Jahre stabil.",
    "s15_caption_1": "Weickert Special: Feinste Wollfaserqualität mit maximaler Standzeit",
