    "s23_subtitle": "Nachspannen des Kernholzes zur Erzeugung maximaler elastischer Außenspannung",
    "s23_bullet_1": "<strong>Schließen der Seitenbacken:</strong> Die temperierten Pressbacken umschließen den Filz seitlich und führen ihn um das beleimte Kernholz.",
    "s23_bullet_2": "<strong>Kernholz nachspannen:</strong> Nachdem die Seitenbacken geschlossen sind, wird das Kernholz nochmals mit Hochdruck nachgespannt.",
    "s23_bullet_3": "<strong>Zugspannung in den Außenlagen:</strong> Durch diesen Renner-spezifischen Schritt erhalten die äußeren Filzlagen eine unerreichte Vorspannung.",
    "s23_bullet_4": "<strong>Basis für die spätere Intonation:</strong> Diese elastische Eigenspannung erlaubt späteres Intonieren mit unvergleichlicher Dynamikspreizung.",
    "s23_caption_1": "Press- und Verleimvorgang des Hammerkopfs unter Hochdruck",
