    "s40_c1_title": "Rechtwinkliger Anschlag",
    "s40_c2_title": "Stielüberhang",
    "s40_c1_desc": "Der Hammer muss im Moment des Saitenkontakts exakt im 90°-Winkel auf die Saite treffen. Der Stiel muss ca. 3 mm Überhang haben. Durch die Massenträgheit wird die kinetische Energie gezielt in Richtung Steg geleitet!",
    "s40_caption_1": "Geometrie des Hammerstielwinkels",
    "s40_caption_2": "und Kraftvektor zum Steg",
