    "s41_caption_1": "Messschema zur Ermittlung der Bohrungslänge im Flügel",
    "s41_b1_badge": "計算式算出",
    "s41_b2_badge": "幾何学的基準軸",
    "s41_bullet_1": "<strong>1. 打弦距離とキーの深さ：</strong> アクションの打弦距離（46〜48 mm）とキーの深さ（10〜10.5 mm）を正確に測定。",
    "s41_bullet_2": "<strong>2. フレンジレールの基準線：</strong> 弦下面に対するフレンジレールの高さを基準面として設定。",
    "s41_bullet_3": "<strong>3. 基本公式の適用：</strong> 標準的なグランドピアノではボア長＝全長 - 24 mm。",
    "s41_bullet_4": "<strong>4. 数学的検証：</strong> 強度確保のためシャンク突出量が最低3 mmあることを確認。",
    "s41_notes": "スライド 41: ルイス・レンナー社のドイツ精密製造技術と品質の優位性を解説してください。",
    "s42_category": "第5部：寸法表・幾何学的設計",
    "s42_title": "グランド用とアップライト用の仕様シート徹底比較",
