    "s42_c2_title": "Upright Piano (UP) Formular",
    "s42_c1_desc": "Fokus auf Gesamtlänge, Bohrungslänge, Stielachse, Steigungswinkel und Rake-Winkel (91° Lehre). Speziell für Flach- und Konzertflügel.",
    "s42_c2_desc": "Erfassung von Nussbohrung, Nusskapsel, Hammerlänge ab Achse und Steigungswinkel für Pianinos und Konzertklaviere.",
