    "s43_title": "ハンマーシャンクの事前組み込みと専用工具",
    "s43_subtitle": "Renner Kapselschrauben 4,5x22 mm mit Tellerfedern und Kapselabstandhalter",
    "s43_bullet_1": "<strong>Vormontage in Feldern:</strong> Stiele nach Registerverteilung aufstecken; 1–2 Positionen zwischen Feldern frei lassen.",
    "s43_bullet_2": "<strong>Gewindegang finden:</strong> Bei gebrauchten Leisten Schraube zuerst leicht nach links drehen, bis sie spürbar in den alten Gewindegang einrastet.",
    "s43_bullet_3": "<strong>Renner Flanschschraube (Art. 43-0008745):</strong> 4,5x22 mm mit Tellerfeder-Scheibe und kombiniertem Schlitz/Kreuzschlitz.",
    "s43_bullet_4": "<strong>Werkzeuge:</strong> PZD 2 Ballengriff-Schraubendreher (Art. 43-0008316) und Kapselabstandhalter (Art. 43-0003286).",
