    "s9_subtitle": "Die definierte Faserorientierung als Fundament für Schwingung und Saitenansprache",
    "s9_bullet_1": "<strong>Kardieren (Carding):</strong> Die aufgelockerten Fasern werden über feine Nadelwalzen gekämmt, entwirrt und parallel zueinander angeordnet.",
    "s9_bullet_2": "<strong>Definierte Faserrichtung:</strong> Das so entstehende hauchdünne, weiche Vlies besitzt eine exakt vorgegebene Vorzugsrichtung der Fasern.",
    "s9_bullet_3": "<strong>Schichtung:</strong> Mehrere Vlieslagen werden im Kreuz- und Längsverbund übereinandergelegt, um die gewünschte Plattendicke und Dichteverteilung aufzubauen.",
    "s9_bullet_4": "<strong>Voraussetzung für die Intonation:</strong> Nur parallel geordnete Fasern reagieren bei späteren Intonierarbeiten vorhersehbar und gleichmäßig auf Nadelstiche.",
